function activeScope(){return document.querySelector('.slide.active,[aria-current="true"],[data-loop-active="true"]')||document.querySelector('[data-loop-id]')}
function render(){renderPill();renderPanel();renderPins()}
function renderPill(){const n=events.length;$('.fb').classList.toggle('has',n>0);$('.count').textContent=n}
