function clearEvents(){events=[];persist();render();toast('Cleared')}
function base(type,message){return{id:uid('fb'),type,artifactId:meta.artifactId,artifactVersion:meta.artifactVersion,createdAt:new Date().toISOString(),message,url:location.href}}
function exportBundle(){return{protocol:'loopkit.feedback_bundle.v0',runtimeVersion:VERSION,artifact:{id:meta.artifactId,version:meta.artifactVersion,title:meta.title,description:meta.description,url:location.href,feedback_policy:'single-use'},decisions,agent_instructions:agentInstructions,items:events.slice()}}
